// Standard clinical reference ranges for common lab tests (LOINC codes)
const referenceRanges = {
  '1920-8': { low: 10, high: 40, unit: 'U/L', name: 'AST' },
  '1742-6': { low: 7, high: 56, unit: 'U/L', name: 'ALT' },
  '1975-2': { low: 0.1, high: 1.2, unit: 'mg/dL', name: 'Bilirubin Total' },
  '2093-3': { low: null, high: 200, unit: 'mg/dL', name: 'Total Cholesterol' },
  '2345-7': { low: 70, high: 100, unit: 'mg/dL', name: 'Glucose' },
  '718-7': { low: 13.5, high: 17.5, unit: 'g/dL', name: 'Hemoglobin' },
  '777-3': { low: 150, high: 400, unit: '10^3/uL', name: 'Platelets' },
  '6690-2': { low: 4.5, high: 11.0, unit: '10^3/uL', name: 'WBC' },
};

const results = [];

// Loop through all items
for (const item of $input.all()) {
  const data = item.json;

  // Check if this item is missing reference ranges
  if (data.reference_low === null && data.reference_high === null) {

    // Look up reference range by LOINC code
    const reference = referenceRanges[data.loinc_code];

    if (reference) {
      // Found it! Update the item
      data.reference_low = reference.low;
      data.reference_high = reference.high;
      data.has_reference_range = true;

      console.log(`✅ Added reference for ${reference.name}: ${reference.low}-${reference.high} ${reference.unit}`);
    } else {
      console.log(`⚠️ No reference found for ${data.loinc_code}: ${data.test_name}`);
    }
  }

  results.push({ json: data });
}

console.log(`\n✅ Processed ${results.length} lab results`);

return results;

