const results = [];

// Get all items from the Code node (Fetch Missing References)
const labItems = $node["Fetch Missing References"].json;

// Get all items from OpenAI node  
const aiItems = $input.all();

// They should be in the same order, so merge by index
for (let i = 0; i < aiItems.length; i++) {
  const aiAnalysis = aiItems[i].json.output[0].content[0].text;
  const labData = Array.isArray(labItems) ? labItems[i] : labItems;

  const merged = {
    ...labData,
    classification: aiAnalysis.classification,
    severity_score: aiAnalysis.severity_score,
    clinical_note: aiAnalysis.clinical_note,
    provider_note: aiAnalysis.provider_note,
    action_required: aiAnalysis.action_required
  };

  results.push({ json: merged });
}

return results;
